"use client"; import { useState } from "react"; import { PageShell } from "../../components/layout/PageShell"; import { Card } from "../../components/ui/Card"; import { Button } from "../../components/ui/Button"; import { Input } from "../../components/ui/Input"; import { useRoundAudit } from "../../lib/hooks/useBlobbyApi"; export default function Verify(){const[id,setId]=useState('1'); const q=useRoundAudit(id); const data:any=q.data; return <PageShell eyebrow="Provably fair" title="Verify every round" intro="Lookup VRF, ticket counts, winners, top-ups, prize composition, explorer links, JSON, and CSV."><div className="grid gap-6 lg:grid-cols-[360px_1fr]"><Card><Input value={id} onChange={e=>setId(e.target.value)} placeholder="Round ID"/><div className="mt-4 flex gap-2"><Button href={`/verify/export/round/${id}.json`}>JSON</Button><Button href={`/verify/export/round/${id}.csv`}>CSV</Button></div></Card><Card><h2 className="display-text text-3xl">Round Audit</h2><pre className="mt-4 max-h-[520px] overflow-auto whitespace-pre-wrap rounded-2xl bg-white p-4 text-xs">{JSON.stringify(data||{},null,2)}</pre></Card></div></PageShell>}
